let user,state,activeMap,mapTimer,liveDriversTimer,liveDriverMarkers=new Map(),liveDriverRoutes=new Map(),onlinePlayers=[],allPlayers=[],presenceStop,presenceTimer,progressStop,progressWrite=Promise.resolve(),currentOffers=[],activeOfferKey='',rentalTimer,clockTimer;const $=s=>document.querySelector(s),money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
function key(){return'rota-brasil-'+user.uid}function fresh(){return{xp:0,balance:0,deliveries:0,km:0,city:'Jundiaí',history:[],ledger:[],trip:null,rentalPaidOn:'',rentalExemptOn:'',rentalRefunded:false,truck:'tia',loan:null,companyName:'',savedAt:0}}function load(){try{return{...fresh(),...JSON.parse(localStorage.getItem(key()))}}catch{return fresh()}}function save(){state.savedAt=Date.now();localStorage.setItem(key(),JSON.stringify(state));chrome();syncProgress();syncPresence()}
function addLedger(type,amount,title,details='',at=Date.now(),ref=''){state.ledger=Array.isArray(state.ledger)?state.ledger:[];state.ledger.unshift({id:crypto.randomUUID?.()||String(Date.now()+Math.random()),type,amount:Number(amount)||0,title,details,at,ref})}
function firstSaturdayFromAccount(){const created=new Date(user?.metadata?.creationTime||Date.now()),parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(created).filter(p=>p.type!=='literal').map(p=>[p.type,p.value])),date=new Date(Date.UTC(+parts.year,+parts.month-1,+parts.day));while(date.getUTCDay()!==6)date.setUTCDate(date.getUTCDate()+1);return date.toISOString().slice(0,10)}
function applyRentalExemption(){state.ledger=(state.ledger||[]).filter(item=>item.ref!=='rental-refund');state.rentalExemptOn=state.rentalExemptOn||firstSaturdayFromAccount();if(state.rentalPaidOn&&!state.rentalRefunded){state.balance+=700;state.rentalRefunded=true;state.rentalExemptOn=state.rentalPaidOn;save();return true}return false}
function level(xp){return Math.max(1,Math.floor(Math.cbrt(xp/35))+1)}function bounds(l){return{start:35*(l-1)**3,end:35*l**3}}function progress(){const l=level(state.xp),b=bounds(l);return{l,now:state.xp-b.start,need:b.end-b.start,pct:Math.round((state.xp-b.start)/(b.end-b.start)*100)}}function reward(km){const truck=currentTruck(),capacityBonus=truck.multiplier;return{pay:Math.round((95+km*2.15)*capacityBonus),xp:Math.max(8,Math.round(km*.28))}}
function routeMinutes(r){const h=+(r.time.match(/(\d+)h/)||[0,0])[1],m=+(r.time.match(/(\d+)\s*min/)||[0,0])[1];return h*60+m}function formatTime(ms){const total=Math.max(0,Math.ceil(ms/1000)),h=Math.floor(total/3600),m=Math.floor(total%3600/60),s=total%60;return(h?h+'h ':'')+String(m).padStart(2,'0')+'m '+String(s).padStart(2,'0')+'s'}function tripStatus(){if(!state.trip)return null;const total=state.trip.end-state.trip.start,remain=Math.max(0,state.trip.end-Date.now()),pct=Math.min(1,Math.max(0,1-remain/total));return{pct,remain,km:Math.max(0,state.trip.totalKm*(1-pct))}}
function tripForCloud(trip){if(!trip)return null;return{...trip,path:(trip.path||[]).map(point=>Array.isArray(point)?{lat:Number(point[0]),lng:Number(point[1])}:{lat:Number(point.lat),lng:Number(point.lng)})}}
function tripFromCloud(trip){if(!trip)return null;return{...trip,path:(trip.path||[]).map(point=>Array.isArray(point)?point:[Number(point.lat),Number(point.lng)])}}
function stateForCloud(){return{...state,uid:user.uid,trip:tripForCloud(state.trip)}}
function syncProgress(){if(!user||!state)return Promise.resolve();const owner=user.uid,payload=stateForCloud();progressWrite=progressWrite.catch(()=>{}).then(()=>setDoc(doc(db,'progress',owner),payload,{merge:false})).catch(error=>console.warn('Não foi possível salvar o progresso na nuvem:',error.code||error.message));return progressWrite}
async function restoreProgress(){const local=load();try{const snapshot=await getDoc(doc(db,'progress',user.uid));if(!snapshot.exists())return local;const remote=snapshot.data();return{...fresh(),...remote,history:Array.isArray(remote.history)?remote.history:[],ledger:Array.isArray(remote.ledger)?remote.ledger:[],trip:tripFromCloud(remote.trip)}}catch(error){console.warn('Não foi possível restaurar o progresso da nuvem:',error.code||error.message);return local}}function normalizeCloudState(remote){return{...fresh(),...remote,history:Array.isArray(remote.history)?remote.history:[],ledger:Array.isArray(remote.ledger)?remote.ledger:[],trip:tripFromCloud(remote.trip)}}function watchProgress(){progressStop?.();const owner=user.uid;progressStop=onSnapshot(doc(db,'progress',owner),snapshot=>{if(!snapshot.exists()||!user||user.uid!==owner||!state)return;const remote=snapshot.data();if((Number(remote.savedAt)||0)<=(Number(state.savedAt)||0))return;state=normalizeCloudState(remote);localStorage.setItem(key(),JSON.stringify(state));chrome();route()},error=>console.warn('Sincronização entre dispositivos indisponível:',error.code||error.message))}
async function syncPresence(){if(!user||!state)return;try{await setDoc(doc(db,'players',user.uid),{uid:user.uid,name:user.displayName||'Motorista',photo:user.photoURL||'',level:level(state.xp),balance:state.balance,km:state.km,city:state.city,destination:state.trip?.to||'',company:state.trip?.company||'',companyName:state.companyName||'',trip:tripForCloud(state.trip),status:state.trip?'Em viagem':'Online',lastSeen:serverTimestamp()},{merge:true})}catch(error){console.warn('Presença multiplayer indisponível:',error.code||error.message)}}
