function chrome(){const p=progress();$('#top-balance').textContent=money(state.balance);$('#user-name').textContent=(user.displayName||'Motorista').split(' ')[0];$('#top-level').textContent='Nível '+p.l;$('#user-photo').src=user.photoURL||avatar(user.displayName||'M');$('.location b').textContent=state.city+', SP';$('.side-status').classList.toggle('working',!!state.trip);$('.side-status span').innerHTML=state.trip?companyLogoByName(state.trip.company)+'<b>Em entrega</b><small>'+state.trip.company+' · '+state.trip.to+'</small>':'Base '+state.city+'<small>Conectado · operação normal</small>'}
