const brandIds={CC:'coca-cola-femsa',KL:'klabin',FI:'fini',BO:'bosch',PI:'pirelli',SA:'samsung',VW:'volkswagen',MB:'mercedes-benz',BA:'bauducco',TY:'toyota',SR:'sorocaba-refrescos',UN:'unipar',US:'usiminas',YA:'yara',BD:'bridgestone',RH:'rhodia'},brandFiles={CC:'coca-cola-logo.svg',PE:'pepsico.svg',HE:'heineken.svg',AI:'aisin.svg',JB:'jbs.svg',SI:'simpress.svg',HA:'harald.svg',HS:'hersheys.svg',GO:'vinicola-goes.svg',MO:'mondiale.svg',SH:'schaeffler.svg',CP:'corr-plastik.svg',IS:'isoforma.svg',FL:'flamboia.svg',AC:'ache.svg',CU:'cummins.svg'};
function companyLogo(factory,small=false){const file=brandFiles[factory.code],brand=brandIds[factory.code];if(file)return'<div class="factory-brand local-brand '+(small?'small':'')+'"><img src="assets/brands/'+file+'" alt="Logo '+factory.name+'"></div>';if(brand)return'<svg class="factory-brand '+(small?'small':'')+'" role="img" aria-label="Logo '+factory.name+'"><use href="assets/brands/factory-logos.svg#'+brand+'"></use></svg>';return'<div class="factory-brand factory-initial '+(small?'small':'')+'">'+escapeHTML(factory.code)+'</div>'}
