function offerCycleKey(){const p=brazilNow();return p.year+p.month+p.day+p.hour}
function nextOfferHour(){const hour=(Number(brazilNow().hour)+1)%24;return String(hour).padStart(2,'0')+':00h'}
function travelMinutes(km){return Math.max(20,Math.round(10+km*.9))}
function travelTime(km){const minutes=travelMinutes(km),hours=Math.floor(minutes/60),rest=minutes%60;return hours?(hours+'h '+String(rest).padStart(2,'0')+'min'):(minutes+' min')}
