function buildOffers(){const truck=currentTruck(),destinations=(routes[state.city]||[]).filter(r=>r.km<=truck.range),companies=factoryData[state.city]||[],key=offerCycleKey(),random=offerRandom(state.city+key);activeOfferKey=key;if(!destinations.length||!companies.length)return[];return Array.from({length:3},(_,i)=>{const route=destinations[Math.floor(random()*destinations.length)],company=companies[Math.floor(random()*companies.length)],items=company.products.split(',');return{...route,company,cargo:items[Math.floor(random()*items.length)].trim()+' para operação regional',offerKey:key,index:i}})}
function routeCard(r,i){const rw=reward(r.km);return'<article class="job route-job"><div class="job-top">'+companyLogo(r.company,true)+'<span class="distance">'+r.km+' KM · '+travelTime(r.km).toUpperCase()+'</span></div><h3>'+r.cargo+'</h3><span class="route">'+state.city+', SP → '+r.to+', SP</span><div class="job-meta"><div>CONTRATANTE<b>'+r.company.name+'</b></div><div>EXPERIÊNCIA<b>+'+rw.xp+' XP</b></div><div>FRETE<b>'+money(rw.pay)+'</b></div></div><div class="job-actions"><button data-preview="'+i+'">VISUALIZAR ROTA NO MAPA</button><button data-job="'+i+'" '+(state.trip?'disabled':'')+'>'+(state.trip?'VIAGEM EM ANDAMENTO':'ACEITAR ENTREGA')+'</button></div></article>'}
