function pathPosition(path,pct){if(path.length<2)return path[0];const lengths=[];let total=0;for(let i=1;i<path.length;i++){const n=activeMap.distance(path[i-1],path[i]);lengths.push(n);total+=n}let target=total*pct;for(let i=0;i<lengths.length;i++){if(target<=lengths[i]){const r=target/lengths[i];return[path[i][0]+(path[i+1][0]-path[i][0])*r,path[i][1]+(path[i+1][1]-path[i][1])*r]}target-=lengths[i]}return path.at(-1)}
