function companiesPage(){const catalog=[...new Map(Object.values(factoryData).flat().map(factory=>[factory.name,factory])).values()].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')),listed=catalog.filter(factory=>companyMarket[factory.name]);$('#view').innerHTML=heading('INTELIGÊNCIA DE MERCADO','Empresas','Compare as companhias que movimentam as cargas do jogo e acompanhe as listadas em bolsa.')+'<section class="market-summary"><article><span>EMPRESAS CADASTRADAS</span><b>'+catalog.length+'</b><small>operações reais presentes no jogo</small></article><article><span>NEGOCIADAS EM BOLSA</span><b>'+listed.length+'</b><small>com cotação de mercado</small></article><article><span>EMPRESAS PRIVADAS</span><b>'+(catalog.length-listed.length)+'</b><small>sem ações negociadas publicamente</small></article></section><section class="stock-terminal"><header><div><span><i></i>COTAÇÕES DE MERCADO</span><h2>Bolsa de valores</h2><p>Preços e variações fornecidos pelo TradingView, sujeitos ao atraso de cada bolsa. Compare a variação percentual; preços em moedas diferentes não são diretamente equivalentes.</p></div><b>MERCADO</b></header><div id="market-widget" class="tradingview-widget-container"></div></section><section class="company-directory"><div class="section-head"><h2>TODAS AS EMPRESAS DO JOGO</h2><span>'+catalog.length+' COMPANHIAS</span></div><div class="company-market-grid">'+catalog.map(factory=>{const market=companyMarket[factory.name];return'<article class="company-market-card">'+companyLogo(factory,true)+'<div><span>'+escapeHTML(factory.sector.toUpperCase())+'</span><h3>'+escapeHTML(factory.name)+'</h3><p>'+escapeHTML(factory.place)+'</p></div>'+(market?'<aside class="is-listed"><b>'+market.ticker+'</b><small>'+market.exchange+(market.note?' · '+market.note:'')+'</small></aside>':'<aside><b>PRIVADA</b><small>Sem ações em bolsa</small></aside>')+'</article>'}).join('')+'</div></section>';mountMarketWidget(listed)}
function mountMarketWidget(listed){const container=document.querySelector('#market-widget');if(!container)return;const script=document.createElement('script');script.src='https://s3.tradingview.com/external-embedding/embed-widget-market-overview.js';script.async=true;script.textContent=JSON.stringify({colorTheme:'dark',dateRange:'1D',showChart:true,locale:'br',width:'100%',height:620,isTransparent:true,showSymbolLogo:true,showFloatingTooltip:false,tabs:[{title:'Empresas do jogo',symbols:listed.map(factory=>({s:companyMarket[factory.name].symbol,d:factory.name}))}]});container.appendChild(script)}function mapPage(){const current=cities[state.city],trip=state.trip,status=tripStatus();$('#view').innerHTML=heading('CENTRAL GEOGRÁFICA','Mapa do Brasil',trip?'Acompanhe seu caminhão em tempo real até '+trip.to+'.':'Arraste para explorar, use os controles de zoom e clique em uma cidade para abrir sua página.')+'<section class="map-shell"><div class="map-toolbar"><div><i></i><span>'+(trip?'VIAGEM EM ANDAMENTO':'POSIÇÃO ATUAL')+'<strong>'+(trip?trip.from+' → '+trip.to:state.city+', SP')+'</strong></span></div>'+(trip?'<div class="trip-summary"><b id="trip-time">'+formatTime(status.remain)+'</b><small id="trip-km">'+status.km.toFixed(1)+' km restantes</small></div>':'')+'<button id="map-current">MINHA POSIÇÃO</button><button id="map-brazil">VER BRASIL INTEIRO</button></div><div id="game-map" aria-label="Mapa interativo do Brasil com a posição atual e cidades disponíveis"></div><div class="map-legend"><span><i class="current-dot"></i>'+(trip?'CAMINHÃO EM MOVIMENTO':'VOCÊ ESTÁ AQUI')+'</span><span><i></i>CIDADE DISPONÍVEL</span><small>CLIQUE NOS PONTOS PARA ABRIR A CIDADE</small></div></section>';if(!window.L){$('#game-map').innerHTML='<p class="map-error">Não foi possível carregar o mapa. Verifique sua conexão.</p>';return}activeMap=L.map('game-map',{zoomControl:true,minZoom:3,maxZoom:14,maxBounds:[[-35.5,-74],[6,-32]],maxBoundsViscosity:.8}).setView([current.lat,current.lng],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(activeMap);Object.entries(cities).forEach(([name,c])=>{const here=name===state.city&&!trip,icon=L.divIcon({className:'city-marker-wrap',html:'<button class="city-marker '+(here?'is-current':'')+'" aria-label="'+name+'"><i></i><span>'+name+'</span></button>',iconSize:[100,48],iconAnchor:[50,24]});L.marker([c.lat,c.lng],{icon,title:name}).addTo(activeMap).on('click',()=>location.hash='cidade/'+encodeURIComponent(name))});let liveMarker;if(trip){const path=trip.path?.length?trip.path:[[cities[trip.from].lat,cities[trip.from].lng],[cities[trip.to].lat,cities[trip.to].lng]];L.polyline(path,{color:'#ff9d42',weight:4,opacity:.8}).addTo(activeMap);const update=()=>{const s=tripStatus();if(!s||s.remain<=0){finishTrip();return}const pos=pathPosition(path,s.pct),icon=L.divIcon({className:'truck-marker-wrap',html:'<div class="truck-marker">🚚<span>'+formatTime(s.remain)+'<small>'+s.km.toFixed(1)+' km</small></span></div>',iconSize:[150,60],iconAnchor:[30,30]});if(liveMarker)liveMarker.setLatLng(pos).setIcon(icon);else liveMarker=L.marker(pos,{icon,zIndexOffset:1000}).addTo(activeMap);$('#trip-time').textContent=formatTime(s.remain);$('#trip-km').textContent=s.km.toFixed(1)+' km restantes'};update();mapTimer=setInterval(update,1000);activeMap.fitBounds(L.latLngBounds(path),{padding:[50,50]})}else{(routes[state.city]||[]).forEach(r=>L.polyline([[current.lat,current.lng],[cities[r.to].lat,cities[r.to].lng]],{color:'#c5f24a',weight:2,opacity:.55,dashArray:'5 7'}).addTo(activeMap))}$('#map-current').onclick=()=>{if(trip&&liveMarker)activeMap.flyTo(liveMarker.getLatLng(),10,{duration:.8});else activeMap.flyTo([current.lat,current.lng],9,{duration:.8})};$('#map-brazil').onclick=()=>activeMap.flyTo([-14.2,-51.9],4,{duration:.8});setTimeout(()=>activeMap.invalidateSize(),50)}
function remoteTripStatus(trip){if(!trip?.start||!trip?.end)return null;const total=Math.max(1,trip.end-trip.start),remain=Math.max(0,trip.end-Date.now()),pct=Math.min(1,Math.max(0,1-remain/total));return{pct,remain,km:Math.max(0,(Number(trip.totalKm)||0)*(1-pct))}}
function driverIcon(player){const zoom=activeMap?.getZoom()||7,size=Math.max(34,Math.min(82,34+(zoom-5)*8)),status=remoteTripStatus(player.trip),traveling=!!status&&status.remain>0,photo=escapeHTML(player.photo||avatar(player.name));return L.divIcon({className:'live-player-wrap',html:'<div class="live-player '+(traveling?'is-driving':'')+'" style="--player-size:'+size+'px"><img src="'+photo+'" alt=""><span>'+escapeHTML(player.name)+'<small>'+(traveling?'🚚 '+formatTime(status.remain)+' · '+status.km.toFixed(1)+' km':'📍 '+escapeHTML(player.city))+'</small></span></div>',iconSize:[size+145,size+20],iconAnchor:[size/2,size/2]})}
function renderLiveDrivers(){if(!activeMap)return;const visible=new Set;onlinePlayers.forEach(player=>{let position,path=null;if(player.trip&&player.trip.end>Date.now()&&cities[player.trip.from]&&cities[player.trip.to]){const status=remoteTripStatus(player.trip);path=player.trip.path?.length?player.trip.path:[[cities[player.trip.from].lat,cities[player.trip.from].lng],[cities[player.trip.to].lat,cities[player.trip.to].lng]];position=pathPosition(path,status.pct)}else{const city=cities[player.city];if(!city)return;position=[city.lat,city.lng]}visible.add(player.uid);let marker=liveDriverMarkers.get(player.uid);if(marker)marker.setLatLng(position).setIcon(driverIcon(player));else{marker=L.marker(position,{icon:driverIcon(player),zIndexOffset:2000}).addTo(activeMap);liveDriverMarkers.set(player.uid,marker)}const oldRoute=liveDriverRoutes.get(player.uid);if(path&&!oldRoute){liveDriverRoutes.set(player.uid,L.polyline(path,{color:player.uid===user.uid?'#ff9d42':'#64c8ff',weight:3,opacity:.7,dashArray:player.uid===user.uid?null:'8 8'}).addTo(activeMap))}else if(!path&&oldRoute){oldRoute.remove();liveDriverRoutes.delete(player.uid)}});for(const[uid,marker]of liveDriverMarkers)if(!visible.has(uid)){marker.remove();liveDriverMarkers.delete(uid);liveDriverRoutes.get(uid)?.remove();liveDriverRoutes.delete(uid)}}
function driverLiveCard(player){const trip=player.trip,status=remoteTripStatus(trip);if(!trip||!status||status.remain<=0)return'<div class="driver-live-card"><span>MOTORISTA</span><h3>'+escapeHTML(player.name)+'</h3><p>Parado em '+escapeHTML(player.city)+', SP</p></div>';const started=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(trip.start)),pct=Math.round(status.pct*100);return'<div class="driver-live-card"><span>ACOMPANHAMENTO AO VIVO</span><h3>'+escapeHTML(player.name)+'</h3><p>'+escapeHTML(trip.from)+' → '+escapeHTML(trip.to)+'</p><div class="driver-live-route"><i style="width:'+pct+'%"></i></div><small>'+pct+'% DO TRAJETO CONCLUÍDO</small><dl><div><dt>ACEITOU ÀS</dt><dd>'+started+'</dd></div><div><dt>TEMPO RESTANTE</dt><dd>'+formatTime(status.remain)+'</dd></div><div><dt>DISTÂNCIA RESTANTE</dt><dd>'+status.km.toFixed(1)+' km</dd></div><div><dt>DISTÂNCIA TOTAL</dt><dd>'+trip.totalKm+' km</dd></div></dl><b>'+escapeHTML(trip.company||'Empresa local')+'</b><em>'+escapeHTML(trip.cargo||'Carga em transporte')+'</em></div>'}
const baseRenderLiveDrivers=renderLiveDrivers;renderLiveDrivers=function(){baseRenderLiveDrivers();onlinePlayers.forEach(player=>{const marker=liveDriverMarkers.get(player.uid);if(!marker)return;const content=driverLiveCard(player),popup=marker.getPopup();if(popup)popup.setContent(content);else marker.bindPopup(content,{className:'driver-live-popup',minWidth:265,maxWidth:310,offset:[18,0]})})};
