function profile(){const p=progress(),name=user.displayName||'Motorista';$('#view').innerHTML=heading('CARTEIRA PROFISSIONAL','Meu perfil','Seu histórico e evolução como motorista.')+'<div class="profile-grid"><aside class="panel identity"><img class="avatar" src="'+(user.photoURL||avatar(name))+'" alt=""><h2>'+name+'</h2><p>REGISTRO RL-'+user.uid.slice(0,8).toUpperCase()+'</p><div class="profile-data"><div><span>Localização atual</span><b>'+state.city+', SP</b></div><div><span>Saldo</span><b>'+money(state.balance)+'</b></div><div><span>Entregas</span><b>'+state.deliveries+'</b></div><div><span>Distância</span><b>'+state.km+' km</b></div></div><button class="logout-button" type="button" data-logout>SAIR DA CONTA</button></aside><section class="panel profile-main"><h2>PROGRESSÃO DO MOTORISTA</h2><div class="level-row"><div><span>NÍVEL ATUAL</span><b>'+p.l+'</b></div><span>'+p.now+' / '+p.need+' XP</span></div><div class="xpbar"><i style="width:'+p.pct+'%"></i></div><div class="progress-label"><span>'+p.pct+'% concluído</span><span>Progressão infinita e lenta</span></div><div class="milestones"><h2>PLANO DE CARREIRA</h2><div class="milestone done"><i></i><div><b>Motorista contratado</b><small>Entregas com veículo fornecido pela empresa.</small></div></div><div class="milestone '+(p.l>=10?'done':'')+'"><i></i><div><b>Comprar o primeiro caminhão · Nível 10</b><small>Tenha seu veículo e receba uma parcela maior do frete.</small></div></div><div class="milestone '+(p.l>=25?'done':'')+'"><i></i><div><b>Abrir transportadora · Nível 25</b><small>Contrate motoristas e administre sua própria empresa.</small></div></div></div></section></div>';document.querySelector('[data-logout]').onclick=logout}
function financialEntries(){const entries=[...(Array.isArray(state.ledger)?state.ledger:[])],refs=new Set(entries.map(item=>item.ref).filter(Boolean));(state.history||[]).forEach((trip,index)=>{const ref=trip.id?'delivery-'+trip.id:'legacy-delivery-'+index;if(!refs.has(ref))entries.push({id:ref,type:'credit',amount:Number(trip.pay)||0,title:'Pagamento de entrega',details:(trip.company?trip.company+' · ':'')+(trip.from||'?')+' → '+(trip.to||'?')+' · '+(trip.km||0)+' km',at:trip.at||0,ref,legacy:true})});if(state.loan&&state.loan.principal&&!entries.some(item=>item.ref==='loan-credit'))entries.push({id:'legacy-loan',type:'credit',amount:Number(state.loan.principal)||45000,title:'Empréstimo bancário',details:'Crédito recuperado do contrato atual.',at:0,ref:'loan-credit',legacy:true});if(state.truck==='agrale8500'&&!entries.some(item=>item.ref==='truck-agrale'))entries.push({id:'legacy-truck',type:'debit',amount:50000,title:'Compra do Agrale 8500',details:'Aquisição recuperada do patrimônio da conta.',at:0,ref:'truck-agrale',legacy:true});return entries.sort((a,b)=>(Number(b.at)||0)-(Number(a.at)||0))}
function balancePage(){const entries=financialEntries(),income=entries.filter(item=>item.type==='credit').reduce((sum,item)=>sum+item.amount,0),expense=entries.filter(item=>item.type==='debit').reduce((sum,item)=>sum+item.amount,0),formatDate=at=>at?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}).format(new Date(at)):'REGISTRO ANTIGO';$('#view').innerHTML=heading('CONTROLE FINANCEIRO','Saldo','Veja de onde o dinheiro entrou, onde foi gasto e o histórico recuperado da sua carreira.')+'<section class="balance-summary"><article><span>SALDO DISPONÍVEL</span><b>'+money(state.balance)+'</b><small>Valor atual da conta</small></article><article><span>TOTAL DE ENTRADAS</span><b class="credit">+'+money(income)+'</b><small>'+entries.filter(item=>item.type==='credit').length+' movimentações recuperadas</small></article><article><span>TOTAL DE SAÍDAS</span><b class="debit">-'+money(expense)+'</b><small>'+entries.filter(item=>item.type==='debit').length+' movimentações recuperadas</small></article></section><section class="statement"><header><div><p class="eyebrow">EXTRATO DA CARREIRA</p><h2>Histórico do saldo</h2></div><span>'+entries.length+' LANÇAMENTOS</span></header><div class="statement-list">'+(entries.length?entries.map(item=>'<article class="statement-row '+item.type+'"><i>'+(item.type==='credit'?'↗':'↙')+'</i><div><b>'+escapeHTML(item.title)+'</b><p>'+escapeHTML(item.details||'Movimentação da conta')+'</p><small>'+formatDate(item.at)+(item.legacy?' · HISTÓRICO RECUPERADO':'')+'</small></div><strong>'+(item.type==='credit'?'+':'-')+money(item.amount)+'</strong></article>').join(''):'<div class="statement-empty">Nenhuma movimentação registrada ainda.</div>')+'</div></section>'}
