const loanPlans={8:{rate:.08},16:{rate:.18},24:{rate:.30},36:{rate:.48}};function loanQuote(weeks){const plan=loanPlans[weeks],total=Math.round(45000*(1+plan.rate)),weekly=Math.ceil(total/weeks);return{weeks:+weeks,rate:plan.rate,total,weekly}}
