function bankPage(){const active=state.loan?.active,quote=loanQuote(8);$('#view').innerHTML=heading('BANCO LONER','Crédito para crescer','Financiamento semanal para comprar seu primeiro caminhão.')+(active?'<section class="loan-active"><p class="eyebrow">EMPRÉSTIMO ATIVO</p><h2>'+money(state.loan.remainingBalance)+'</h2><span>SALDO DEVEDOR</span><div><b>'+state.loan.remainingWeeks+'</b><small>PARCELAS RESTANTES</small></div><div><b>'+money(state.loan.weekly)+'</b><small>TODO SÁBADO</small></div><p>As parcelas são cobradas mesmo quando seu saldo estiver insuficiente.</p></section>':'<section class="bank-offer"><div><p class="eyebrow">CRÉDITO PRÉ-APROVADO</p><h2>'+money(45000)+'</h2><p>Escolha o prazo. Quanto maior o número de semanas, maiores serão os juros totais.</p></div><aside><label for="loan-weeks">PRAZO DE PAGAMENTO</label><select id="loan-weeks"><option value="8">8 semanas · 8% de juros</option><option value="16">16 semanas · 18% de juros</option><option value="24">24 semanas · 30% de juros</option><option value="36">36 semanas · 48% de juros</option></select><dl><div><dt>VALOR RECEBIDO</dt><dd>'+money(45000)+'</dd></div><div><dt>TOTAL A PAGAR</dt><dd id="loan-total">'+money(quote.total)+'</dd></div><div><dt>PARCELA SEMANAL</dt><dd id="loan-weekly">'+money(quote.weekly)+'</dd></div></dl><button data-take-loan>CONTRATAR EMPRÉSTIMO</button><small>Débito automático todos os sábados. O saldo poderá ficar negativo.</small></aside></section>');const select=$('#loan-weeks');if(select)select.onchange=()=>{const q=loanQuote(select.value);$('#loan-total').textContent=money(q.total);$('#loan-weekly').textContent=money(q.weekly)};document.querySelector('[data-take-loan]')?.addEventListener('click',takeLoan)}
function takeLoan(){if(state.loan?.active)return;const q=loanQuote($('#loan-weeks').value),p=brazilNow(),today=p.year+'-'+p.month+'-'+p.day;state.balance+=45000;state.loan={active:true,principal:45000,total:q.total,weekly:q.weekly,remainingBalance:q.total,remainingWeeks:q.weeks,rate:q.rate,paidOn:p.weekday==='Sat'?today:''};addLedger('credit',45000,'Empréstimo bancário',q.weeks+' parcelas semanais · total contratado '+money(q.total),Date.now(),'loan-credit');save();toast('Empréstimo aprovado: '+money(45000)+' adicionados ao saldo.');bankPage()}
function companyPage(){if(!state.companyName){$('#view').innerHTML=heading('SEU PRÓXIMO PASSO','Criar minha empresa','Escolha o nome definitivo da sua transportadora para abrir a página dela.')+'<section class="company-create"><div class="company-create-mark">RL</div><div><p class="eyebrow">FUNDAÇÃO DA TRANSPORTADORA</p><h2>Dê um nome ao seu futuro</h2><p>O nome será registrado nesta conta e aparecerá na página da sua empresa.</p><form id="company-form"><label for="company-name">NOME DA EMPRESA</label><input id="company-name" maxlength="32" minlength="3" autocomplete="organization" placeholder="Ex.: Horizonte Transportes" required><small>Use de 3 a 32 caracteres.</small><button type="submit">CRIAR MINHA EMPRESA</button></form></div></section>';$('#company-form').onsubmit=event=>{event.preventDefault();const name=$('#company-name').value.trim().replace(/\s+/g,' ');if(name.length<3){toast('Digite um nome com pelo menos 3 caracteres.');return}state.companyName=name.slice(0,32);save();toast('Transportadora criada com sucesso!');companyPage()};return}const ownedTrucks=state.truck==='agrale8500'?1:0,name=escapeHTML(state.companyName),initials=state.companyName.split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase();$('#view').innerHTML=heading('GESTÃO DA TRANSPORTADORA',name,'Acompanhe o patrimônio e o crescimento da sua empresa.')+'<section class="company-dashboard"><header><div class="company-emblem">'+escapeHTML(initials)+'</div><div><span>TRANSPORTADORA DO JOGADOR</span><h2>'+name+'</h2><p>Fundador: '+escapeHTML(user.displayName||'Motorista')+'</p></div></header><div class="company-stats"><article><span>CAMINHÕES REGISTRADOS</span><b>'+ownedTrucks+'</b><small>Somente veículos próprios entram na frota</small></article><article><span>MOTORISTAS CONTRATADOS</span><b>0</b><small>Você ainda trabalha sozinho</small></article><article><span>QUILÔMETROS DA EMPRESA</span><b>'+Number(state.km).toLocaleString('pt-BR')+'</b><small>km percorridos pelo fundador</small></article></div><div class="company-fleet"><div><p class="eyebrow">FROTA DA EMPRESA</p><h3>'+(ownedTrucks?'1 caminhão registrado':'Nenhum caminhão registrado')+'</h3><p>'+(ownedTrucks?'Seu Agrale 8500 está registrado no patrimônio da transportadora.':'O caminhão da sua tia é emprestado e não pertence à empresa. Compre um veículo próprio para iniciar a frota.')+'</p></div><button data-company-shop>VER CAMINHÕES À VENDA</button></div></section>';document.querySelector('[data-company-shop]').onclick=()=>location.hash='concessionaria'}
function updateOfferClock(){const now=new Date(),remain=3600000-(now.getMinutes()*60000+now.getSeconds()*1000+now.getMilliseconds()),minutes=Math.floor(remain/60000),seconds=Math.floor(remain%60000/1000),display=$('#offer-reset'),validUntil=$('#offer-valid-until');if(display)display.textContent=String(minutes).padStart(2,'0')+':'+String(seconds).padStart(2,'0');if(validUntil)validUntil.textContent=nextOfferHour();if(location.hash==='#entregas'&&activeOfferKey&&activeOfferKey!==offerCycleKey())deliveries()}
function previewOffer(i){const offer=currentOffers[i];if(!offer)return;sessionStorage.setItem('rota-loner-preview',JSON.stringify({from:state.city,...offer}));location.hash='previsao'}
async function routePreviewPage(){let offer;try{offer=JSON.parse(sessionStorage.getItem('rota-loner-preview'))}catch{}if(!offer||!cities[offer.from]||!cities[offer.to]){location.hash='entregas';return}const start=cities[offer.from],end=cities[offer.to];$('#view').innerHTML=heading('PLANEJAMENTO DE ROTA','Prévia da viagem','Confira o caminho antes de aceitar o trabalho.')+'<section class="preview-map-shell"><div class="preview-contract">'+companyLogo(offer.company,true)+'<div><span>ROTA PREVISTA</span><h2>'+offer.from+' → '+offer.to+'</h2><p>'+offer.cargo+'</p></div><dl><div><dt>DISTÂNCIA</dt><dd>'+offer.km+' km</dd></div><div><dt>TEMPO ESTIMADO</dt><dd>'+travelTime(offer.km)+'</dd></div><div><dt>PAGAMENTO</dt><dd>'+money(reward(offer.km).pay)+'</dd></div></dl><button data-preview-back>VOLTAR ÀS OFERTAS</button></div><div id="preview-map"></div></section>';document.querySelector('[data-preview-back]').onclick=()=>location.hash='entregas';if(!window.L){$('#preview-map').innerHTML='<p class="map-error">Não foi possível carregar o mapa.</p>';return}activeMap=L.map('preview-map',{zoomControl:true,minZoom:5,maxZoom:16}).setView([start.lat,start.lng],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(activeMap);L.marker([start.lat,start.lng]).addTo(activeMap).bindTooltip('Origem · '+offer.from,{permanent:true,direction:'top'});L.marker([end.lat,end.lng]).addTo(activeMap).bindTooltip('Destino · '+offer.to,{permanent:true,direction:'top'});let path=[[start.lat,start.lng],[end.lat,end.lng]];try{const response=await fetch('https://router.project-osrm.org/route/v1/driving/'+start.lng+','+start.lat+';'+end.lng+','+end.lat+'?overview=full&geometries=geojson'),data=await response.json();if(data.routes?.[0])path=data.routes[0].geometry.coordinates.map(c=>[c[1],c[0]])}catch{}if(location.hash!=='#previsao'||!activeMap)return;L.polyline(path,{color:'#c5f24a',weight:5,opacity:.9}).addTo(activeMap);activeMap.fitBounds(L.latLngBounds(path),{padding:[45,45]});setTimeout(()=>activeMap?.invalidateSize(),50)}
function bind(){document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>startTrip(+b.dataset.job,b));document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>previewOffer(+b.dataset.preview));document.querySelectorAll('[data-jobs]').forEach(b=>b.onclick=()=>location.hash='entregas')}
async function startTrip(i,button){if(state.trip)return;const r=currentOffers[i],truck=currentTruck();if(!r||r.km>truck.range){toast('Este caminhão não consegue realizar uma viagem acima de '+truck.range+' km.');return}if(r.offerKey!==offerCycleKey()){deliveries();toast('As ofertas foram renovadas. Escolha um novo trabalho.');return}const from=state.city,startCity=cities[from],endCity=cities[r.to];button.disabled=true;button.textContent='CALCULANDO ROTA...';let path=[[startCity.lat,startCity.lng],[endCity.lat,endCity.lng]],totalKm=r.km;try{const res=await fetch('https://router.project-osrm.org/route/v1/driving/'+startCity.lng+','+startCity.lat+';'+endCity.lng+','+endCity.lat+'?overview=full&geometries=geojson'),data=await res.json(),road=data.routes?.[0];if(road)path=road.geometry.coordinates.map(c=>[c[1],c[0]])}catch{}const rw=reward(totalKm),start=Date.now(),duration=travelMinutes(totalKm);state.trip={from,to:r.to,company:r.company.name,cargo:r.cargo,totalKm,path,start,end:start+duration*60000,pay:rw.pay,xp:rw.xp};save();toast('Frete da '+r.company.name+' iniciado para '+r.to+'. Tempo estimado: '+travelTime(totalKm)+'.');location.hash='mapa'}
function finishTrip(){if(!state.trip)return;const t=state.trip,id=crypto.randomUUID?.()||String(Date.now()),at=Date.now();state.xp+=t.xp;state.balance+=t.pay;state.deliveries++;state.km+=t.totalKm;state.city=t.to;state.history.unshift({id,from:t.from,to:t.to,company:t.company,cargo:t.cargo,km:t.totalKm,pay:t.pay,at});addLedger('credit',t.pay,'Pagamento de entrega',t.company+' · '+t.from+' → '+t.to+' · '+t.totalKm+' km',at,'delivery-'+id);state.trip=null;save();clearInterval(mapTimer);toast('Entrega concluída! Você chegou a '+t.to+': +'+t.xp+' XP e '+money(t.pay)+'.');location.hash='home'}
function versionPage(){$('#view').innerHTML=heading('HISTÓRICO DE DESENVOLVIMENTO','Rota Loner v.0.0.25','Acompanhe as novidades e melhorias adicionadas ao jogo.')+'<section class="release-current"><span>VERSÃO ATUAL</span><h2>v.0.0.25</h2><p>Multiplayer rodoviário e expansão do sistema de carreira.</p></section><section class="changelog"><article><time>v.0.0.25 · ATUAL</time><h3>Viagens multiplayer ao vivo</h3><ul><li>Posição simulada dos jogadores no mapa em tempo real.</li><li>Trajeto rodoviário, foto, tempo e distância restantes.</li><li>Painel ao clicar no motorista com carga, empresa e horário de aceite.</li><li>Correção da sincronização das coordenadas no Firebase.</li></ul></article><article><time>v.0.0.24</time><h3>Economia e presença online</h3><ul><li>Nova página Saldo com entradas, saídas e histórico recuperado.</li><li>Ranking por dinheiro, nível e quilômetros percorridos.</li><li>Persistência do progresso entre dispositivos.</li><li>Primeiro sábado isento do aluguel da tia.</li></ul></article><article><time>v.0.0.23</time><h3>Novas cidades e empresas</h3><ul><li>Guarulhos, Cabreúva e São Roque adicionadas ao mapa.</li><li>Novas fábricas, logotipos, cargas e conexões rodoviárias.</li><li>Criação da transportadora própria e controle de frota.</li></ul></article></section>'}
function route(){clearInterval(mapTimer);clearInterval(liveDriversTimer);if(activeMap){activeMap.remove();activeMap=null}if(state?.trip&&state.trip.end<=Date.now()){finishTrip();return}const page=location.hash.slice(1)||'home';document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===page));if(page==='empresas')companiesPage();else if(page==='versao')versionPage();else if(page==='perfil')profile();else if(page==='saldo')balancePage();else if(page==='ranking')ranking();else if(page==='caminhao')truckPageV2();else if(page==='concessionaria')truckShop();else if(page==='banco')bankPage();else if(page==='entregas'||page==='empresa/coca-cola')deliveries();else if(page==='previsao')routePreviewPage();else if(page==='mapa')mapPage();else if(page.startsWith('cidade/'))cityPage(decodeURIComponent(page.slice(7)));else if(page==='empresa')companyPage();else if(state.trip)tripHome();else home();$('.sidebar').classList.remove('open')}
function brazilNow(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return parts}
function updateBrazilClock(){const p=brazilNow(),clock=$('#brasil-clock b');if(clock)clock.textContent=p.day+'/'+p.month+'/'+p.year+' · '+p.hour+':'+p.minute+':'+p.second}
function chargeWeeklyRental(){if(!user||!state)return;const p=brazilNow(),today=p.year+'-'+p.month+'-'+p.day;if(p.weekday!=='Sat')return;state.rentalExemptOn=state.rentalExemptOn||firstSaturdayFromAccount();const charges=[];if(state.truck!=='agrale8500'&&today!==state.rentalExemptOn&&state.rentalPaidOn!==today&&state.balance>=700){state.balance-=700;state.rentalPaidOn=today;addLedger('debit',700,'Aluguel semanal da tia','Cobrança automática de sábado.',Date.now(),'rental-'+today);charges.push('aluguel da tia: -'+money(700))}if(state.loan?.active&&state.loan.paidOn!==today){const payment=Math.min(state.loan.weekly,state.loan.remainingBalance);state.balance-=payment;state.loan.remainingBalance=Math.max(0,state.loan.remainingBalance-payment);state.loan.remainingWeeks=Math.max(0,state.loan.remainingWeeks-1);state.loan.paidOn=today;if(state.loan.remainingBalance<=0||state.loan.remainingWeeks<=0)state.loan.active=false;addLedger('debit',payment,'Parcela do banco','Pagamento semanal do empréstimo.',Date.now(),'loan-payment-'+today);charges.push('parcela do banco: -'+money(payment))}if(!charges.length)return;save();toast('Débito de sábado · '+charges.join(' · ')+'.')}
async function enter(u){user=u;state=await restoreProgress();localStorage.setItem(key(),JSON.stringify(state));await syncProgress();$('#login').classList.add('hidden');$('#app').classList.remove('hidden');const rankingLink=document.querySelector('[data-page="ranking"]');if(!document.querySelector('[data-page="saldo"]')){const balanceLink=document.createElement('a');balanceLink.href='#saldo';balanceLink.dataset.page='saldo';balanceLink.innerHTML='<i>R$</i>Saldo';rankingLink.parentNode.insertBefore(balanceLink,rankingLink)}if(!document.querySelector('.sidebar-version')){const versionLink=document.createElement('a');versionLink.href='#versao';versionLink.dataset.page='versao';versionLink.className='sidebar-version';versionLink.innerHTML='<span>VERSÃO DO JOGO</span><b>v.0.0.25</b>';document.querySelector('.side-status').insertAdjacentElement('afterend',versionLink)}document.querySelector('[data-page="mapa"]').lastChild.textContent='Mapa';applyRentalExemption();chrome();syncProgress();watchProgress();watchPresence();route();updateBrazilClock();chargeWeeklyRental();clearInterval(rentalTimer);rentalTimer=setInterval(()=>{updateBrazilClock();updateOfferClock();chargeWeeklyRental()},1000);document.body.classList.remove('auth-pending')}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),4200)}
async function logout(){try{await syncProgress();await signOut(auth)}catch(error){console.warn('Falha ao sair:',error.code||error.message);toast('Não foi possível sair da conta agora.')}}$('#google-login').onclick=async()=>{try{await setPersistence(auth,browserLocalPersistence);$('#auth-message').textContent='Abrindo o login seguro do Google...';await signInWithPopup(auth,provider)}catch(error){console.warn('Falha no login:',error.code||error.message);const blocked=error.code==='auth/popup-blocked',closed=error.code==='auth/popup-closed-by-user';$('#auth-message').textContent=blocked?'Permita a janela de login do Google e tente novamente.':closed?'Login cancelado. Tente novamente quando quiser.':'Não foi possível entrar. Verifique a conexão e tente novamente.'}};$('#profile-shortcut').onclick=()=>location.hash='perfil';$('#menu-toggle').onclick=()=>$('.sidebar').classList.toggle('open');addEventListener('hashchange',route);updateBrazilClock();clearInterval(clockTimer);clockTimer=setInterval(updateBrazilClock,1000);onAuthStateChanged(auth,u=>{if(u)enter(u).catch(error=>{console.error('Falha ao carregar a conta:',error);$('#auth-message').textContent='Sua conta entrou, mas o perfil não pôde ser carregado. Atualize a página.';document.body.classList.remove('auth-pending')});else{progressStop?.();presenceStop?.();clearInterval(presenceTimer);clearInterval(rentalTimer);user=null;state=null;$('#app').classList.add('hidden');$('#login').classList.remove('hidden');$('#auth-message').textContent='';document.body.classList.remove('auth-pending')}});
